let language = 'es';
try { language = localStorage.getItem('prami-language') === 'en' ? 'en' : 'es'; } catch {}
const originalText = new WeakMap();
const originalAttributes = new WeakMap();
function translatePage() {
 const walker = document.createTreeWalker(document.documentElement, NodeFilter.SHOW_TEXT);
 let node;
 while ((node = walker.nextNode())) {
  if (['SCRIPT','STYLE'].includes(node.parentElement?.tagName) || node.parentElement?.closest('[data-language-control]')) continue;
  if (!originalText.has(node)) originalText.set(node, node.nodeValue);
  const source = originalText.get(node), key = source.trim();
  node.nodeValue = language === 'en' && english[key] ? source.replace(key, english[key]) : source;
 }
 document.querySelectorAll('[aria-label],[alt],meta[name="description"]').forEach(element => {
  const attribute = element.tagName === 'META' ? 'content' : element.tagName === 'IMG' ? 'alt' : 'aria-label';
  if (!originalAttributes.has(element)) originalAttributes.set(element, element.getAttribute(attribute));
  let source = originalAttributes.get(element);
  if (element.classList.contains('menu')) source = element.getAttribute('aria-expanded') === 'true' ? 'Cerrar menú' : 'Abrir menú';
  element.setAttribute(attribute, language === 'en' ? (english[source] || source) : source);
 });
 document.documentElement.lang = language;
 document.querySelector('#language').value = language;
}
function setLanguage(value) {
 language = value === 'en' ? 'en' : 'es';
 try { localStorage.setItem('prami-language', language); } catch {}
 translatePage();
}
document.querySelector('#language').addEventListener('change', event => setLanguage(event.target.value));
document.addEventListener('DOMContentLoaded', translatePage);
